def load_service_templates(apps, schema_editor):
    Tradition = apps.get_model("traditions", "Tradition")
    ServiceTemplate = apps.get_model("traditions", "ServiceTemplate")
    SongSlot = apps.get_model("traditions", "SongSlot")
    for tradition_code, templates in SERVICE_TEMPLATES.items():
        tradition = Tradition.objects.filter(code=tradition_code).first()
        if tradition is None:
            continue
        for code, name, slots in templates:
            template, _ = ServiceTemplate.objects.update_or_create(
                tradition=tradition, code=code, defaults={"name": name}
            )
            for position, slot_name in enumerate(slots, start=1):
                SongSlot.objects.update_or_create(
                    template=template, position=position, defaults={"name": slot_name}
                )


